\newcommand*{\todo}[3][]{%
  \begingroup%
  \edef\@isdone{#1}\def\@donestring{done}\def\@doneflag{}%
  \edef\@authors{#2}\def\@task{#3}%<-- not expand this one
  \def\do##1{@##1\space}%
  \def\printauthors{%
    \expandafter\docsvlist\expandafter{\@authors}%
  }%
  \ifdefstrequal{\@isdone}{\@donestring}{%
    \def \@doneflag{x\space}%
    [\textcolor{lightgray}{\texttt{\printauthors \textbf{:} \@task}}]%
  } {[\texttt{\textcolor{red}{\textbf{\printauthors}}\textbf{:} \@task}]}%
  \immediate\write\@todofile{\@doneflag \expandonce{\@task} \space \printauthors}%
  \endgroup%
}
\makeatother

